const adminTemplateStatus = `-- name: AdminTemplateStatus :one
SELECT
    (SELECT COUNT(*) FROM shops WHERE shops.category = $1)::bigint AS shops,
    (SELECT COUNT(*) FROM products p JOIN shops s ON s.id = p.shop_id
      WHERE s.category = $1 AND p.template_key = ANY($2::text[]))::bigint AS present_rows,
    (SELECT COUNT(*) FROM products p JOIN shops s ON s.id = p.shop_id
      WHERE s.category = $1
        AND p.template_key IS NOT NULL
        AND NOT (p.template_key = ANY($2::text[])))::bigint AS stale_rows
`

type AdminTemplateStatusParams struct {
	Category string   `json:"category"`
	Column2  []string `json:"column_2"`
}

type AdminTemplateStatusRow struct {
	Shops       int64 `json:"shops"`
	PresentRows int64 `json:"present_rows"`
	StaleRows   int64 `json:"stale_rows"`
}

func (q *Queries) AdminTemplateStatus(ctx context.Context, arg AdminTemplateStatusParams) (AdminTemplateStatusRow, error) {
	row := q.db.QueryRow(ctx, adminTemplateStatus, arg.Category, arg.Column2)
	var i AdminTemplateStatusRow
	err := row.Scan(&i.Shops, &i.PresentRows, &i.StaleRows)
	return i, err
}

